-- Further Tokat destinations from the Provincial Directorate of Culture and Tourism.
INSERT INTO public.places
(name,category,place_type,city,address,latitude,longitude,slug,short_description,long_description,source_url,external_source,verified,trust_score,is_active,content_review_status,tags)
SELECT v.name,v.category,v.place_type,v.city,v.address,v.latitude,v.longitude,v.slug,v.short_description,v.long_description,v.source_url,'curated_seed',false,85,true,'source_backed',v.tags::jsonb
FROM (VALUES
('Almus Baraj Gölü','Doğa','Baraj gölü','Tokat','Almus, Tokat',40.375,36.900,'curated-tokat-almus-baraj-golu','Geniş su yüzeyi ve çevresindeki ormanlık yamaçlarıyla öne çıkan doğal gezi alanı.','Almus Baraj Gölü, Tokat’ın doğa ve açık hava etkinlikleri için öne çıkan alanlarından biridir; kıyı çevresi manzara ve dinlenme amaçlı ziyaret edilir.','https://tokat.ktb.gov.tr/TR-217256/turizm-aktiviteleri.html','["göl","doğa","manzara","almus"]'),
('Sulusaray Sebastopolis Antik Kenti','Arkeoloji','Antik kent','Tokat','Sulusaray ilçe merkezi, Tokat',40.010,36.085,'curated-tokat-sebastopolis-antik-kenti','Roma dönemine uzanan kalıntılarıyla Sulusaray’ın arkeolojik mirası.','Sebastopolis Antik Kenti, Sulusaray çevresindeki Roma dönemi yerleşiminin izlerini taşıyan arkeolojik alandır; Tokat’ın önemli antik yerleşimlerinden biridir.','https://tokat.ktb.gov.tr/TR-217256/turizm-aktiviteleri.html','["arkeoloji","Roma","antik kent","sulusaray"]'),
('Sulusaray Kaplıcaları','Sağlık ve Doğa','Termal kaynak','Tokat','Sulusaray, Tokat',40.000,36.085,'curated-tokat-sulusaray-kaplicalari','Sulusaray çevresindeki termal kaynaklarla tanınan kaplıca alanı.','Sulusaray kaplıcaları, Tokat’ın termal turizm değerleri arasında anılır; ziyaret öncesinde tesislerin güncel hizmet ve erişim bilgileri kontrol edilmelidir.','https://tokat.ktb.gov.tr/TR-217256/turizm-aktiviteleri.html','["termal","kaplıca","sulusaray"]'),
('Niksar Çamiçi Yaylası','Doğa','Yayla','Tokat','Çamiçi Yaylası, Niksar, Tokat',40.650,37.050,'curated-tokat-niksar-camici-yaylasi','Orman dokusu ve serin yayla havasıyla bilinen doğa alanı.','Niksar yakınındaki Çamiçi Yaylası, Tokat İl Kültür ve Turizm Müdürlüğünün kamp ve karavan turizmi için andığı doğal alanlardan biridir.','https://tokat.ktb.gov.tr/TR-217256/turizm-aktiviteleri.html','["yayla","orman","doğa","niksar"]')
) AS v(name,category,place_type,city,address,latitude,longitude,slug,short_description,long_description,source_url,tags)
WHERE NOT EXISTS (SELECT 1 FROM public.places p WHERE p.slug=v.slug)
  AND NOT EXISTS (SELECT 1 FROM public.places p WHERE p.city=v.city AND lower(trim(p.name))=lower(trim(v.name)));